def unit_of_work(metadata=None, timeout=None):
    def do_work(func):
        def wrapper(*args, **kwargs):
            tx = args[0]
            metadata = metadata or kwargs.get("metadata")
            timeout = timeout or kwargs.get("timeout")
            if metadata:
                tx.metadata.update(metadata)
            if timeout:
                tx.timeout = timeout
            return func(*args, **kwargs)
        return wrapper
    return do_work

def unit_of_work(func):
    def wrapper(tx, *args, **kwargs):
        # Apply metadata
        tx.set_metadata(**kwargs.get("metadata", {}))

        # Apply timeout
        timeout_s = kwargs.get("timeout")
        if timeout_s is not None:
            tx.expiration = timeout_s

        return func(tx, *args, **kwargs)

    return wrapper

