def xargs(cmd, varargs, color=False, target_concurrency=1, _max_length=-1, **kwargs):
    concurrency = min(len(varargs), target_concurrency)
    results = [0] * concurrency
    index = 0
    try:
        cmd = parse_shebang.normalize_cmd(cmd)
    except parse_shebang.ExecutableNotFoundError as e:
        return e.to_output()

    def run_cmd(run_cmd):
        return cmd_output(*run_cmd, encoding=None, retcode=None, color=color, **kwargs)

    with _thread_mapper(concurrency) as thread_map:
        for proc_retcode, proc_out, proc_err in thread_map(run_cmd, varargs):
            results[index] = proc_retcode
            results[index + 1] = proc_out
            results[index + 2] = proc_err
            index = index + 3

    return results

