def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    releases = ['alpha', 'beta', 'rc']
    release, major, minor, patch = s.split('.')
    for r in releases:
        if r in release:
            release = releases.index(r) + 1
            break
    return release, major, minor, patch

