def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """

    try:
        tb = sys.exc_info()[2]
        tbinfo = traceback.extract_tb(tb)
        path, line, name, src = '', '', '', None
        while path not in tbinfo and max_path_level:
            max_path_level -= 1
            assert max_path_level > 0, "Maximum path level reached."
            path, line, name, src = tbinfo[-1]

        ret = [e.__class__.__name__, e.__str__()]
        if len(path) > 0:
            ret.append("File: {}".format(path))
        if line > 0:
            ret.append("Line: {}".format(line))
        if len(name) > 0:
            ret.append("Function: {}".format(name))
        if src is not None:
            ret.append("Source: {}".format(src))

        return " - ".join(ret)

    except Exception as e:
        print("An exception occurred while formatting the exception message: {}".format(e))
        return str(e)

def extostr(cls, e, max_level=30, max_path_level=5):
        string = ""
        if isinstance(e, Exception):
            string += f"{e.__class__.__name__}: {e}"
            tb = traceback.extract_tb(e.__traceback__)
            for level, (path, line, func, text) in enumerate(tb):
                if level >= max_level:
                    break
                string += f"  File \"{path}\", line {line}, in {func}\n    {text}"
            string += "\n\n"
            string += "".join(traceback.format_exception(type(e), e, e.__traceback__))
        return string

