        return

    if isinstance(last_applied_manifest, str):
        raise ValueError("`last_applied_manifest` must be a list")

    if not response:
        raise ValueError("`response` must be a list")

    for i, item in enumerate(response):
        # If last_applied_manifest[i] does not exist, initialize it with {}
