        out_params = {}
        for key, value in params.items():
            try:
                out_params[f"@{key}"] = value
            except KeyError:
                raise ValueError("Parameter name '{}' is not valid".format(key)) from None
        return (sql.format(**out_params), out_params)
    elif isinstance(params, Sequence):
        try:
            out_params = {f"${i+1}": value for i, value in enumerate(params)}
        except IndexError:
            raise ValueError("Number of parameters does not match number of placeholders in query") from None
        return (sql.format(**out_params), out_params)
