        raise ValueError("Must be out_style SQL to use formatmany.")

    # Check that the input types are valid
    if not isinstance(sql, (str, bytes)):
        raise TypeError("SQL query must be a str or bytes")

    if not isinstance(many_params, (list, tuple)):
        raise TypeError("many_params must be a list or tuple")

    for params in many_params:
        if not isinstance(params, (dict, tuple, list)):
            raise TypeError("Paramaters must be a dict, tuple or list")

    # Create a list of tuples to hold the converted out-style parameters
