        # Convert each parameter to an out-style parameter
        out_param = self.out_style.convertParameters(params)

        # Add the converted parameter to the out_params list
        out_params.append(out_param)

    # Replace the in-style parameters in the SQL query with the converted out-style parameters
    query, used_params = self.out_style.reformatQuery(sql, out_params)

    return query, out_params

