def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    if not os.path.exists(path):
        raise InvalidPathError('path %s does not exist' % path)
    if not os.path.isdir(path):
        raise NotDirectoryError('path %s is not a directory' % path)
    if not os.access(path, os.R_OK):
        raise NotReadableError('path %s is not readable' % path)

    # validate ocfldotjson
    try:
        with open(os.path.join(path, 'ocfldotjson'), 'r') as f:
            json.load(f)
    except FileNotFoundError:
        raise FileNotFoundError('ocfldotjson not found in %s' % path)
    except json.JSONDecodeError:
        raise InvalidJsonError('invalid or corrupt ocfldotjson in %s' % path)

    # validate bagit
    bag_path = os.path.join(path, 'bagit')
    if not os.path.exists(bag_path) or not os.path.isdir(bag_path):
        raise BagNotFoundError('no bag in %s' % path)
    if not os.access(bag_path, os.R_OK):
        raise BagNotReadableError('bag in %s not readable' % path)

    try:
        with open(os.path.join(bag_path, 'bagit.txt'), 'r') as f:
            lines = f.readlines()
            if not all(['Bag-Path:' in line for line in lines]):
                raise InvalidBagError('invalid bag in %s' % path)
    except FileNotFoundError:
        raise BagNotFoundError('no bag in %s' % path)

    return True

