def check_digests_present_and_used(manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""

    all_digests_used = set(digests_used)
    all_manifest_digests = set()

    for manifest in manifest_files:
        manifest_digests = manifest.get_digests()
        all_manifest_digests.update(manifest_digests)

    for digest in all_manifest_digests:
        if digest not in all_digests_used:
            raise RuntimeError(f"Manifest digest {digest} is not used")

    for digest in all_digests_used:
        if digest not in all_manifest_digests:
            raise RuntimeError(f"Digest {digest} is used but not present in manifest")

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        all_digests = set()
        for manifest_file in manifest_files:
            all_digests.update(manifest_file["digests"])

        if not all_digests <= digests_used:
            missing_digests = all_digests - digests_used
            raise ValueError(f"Some digests are not used: {missing_digests}")

        return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not manifest_files or not digests_used:
        return

    # Check all manifest files have matching digests
    for manifest_file in manifest_files:
        for digest inifest_file['digest']:
            if digest not in digests_used:
                raise ValueError(f"Missing digest: {digest}")

    # Check all digests in manifest files are used
    for digest in digests_used:
        if digest not in manifest_files_digests:
            raise ValueError(f"Unused digest: {digest}")

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not manifest_files:
        raise ValueError("Must give at least one filename!")
    if not digests_used:
        raise ValueError("Must give at least one digest to use!")

    for manifest_file in manifest_files:
        digests = self.analyzed_files.get(manifest_file)
        if not digests:
            return None

        for digest in digests:
            if digest not in digests_used:
                return None

    return self.analyzed_apk[digest][0]

