def validate_fixity(self, fixity, manifest_files):
    # Check that fixity is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity must be a dictionary")

    # Check that the 'algorithm' key is present and has the correct value
    if 'algorithm' not in fixity or fixity['algorithm'] != 'sha256':
        raise ValueError("Invalid fixity algorithm")

    # Check that the 'hashes' key is present and has the correct type
    if 'hashes' not in fixity or not isinstance(fixity['hashes'], list):
        raise ValueError("Invalid fixity hashes")

    # Check that all hashes are strings
    hashes = fixity['hashes']
    for i, hash_value in enumerate(hashes):
        if not isinstance(hash_value, str):
            raise ValueError(f"Invalid hash value at index {i}: {hash_value}")

    # Check that each hash is of the correct length
    length = len(fixity['algorithm'])
    for i, hash_value in enumerate(hashes):
        if len(hash_value) != length:
            raise ValueError(f"Invalid hash value at index {i}: {hash_value}")

    # Check that all files are in the manifest
    for hash_value in hashes:
        if hash_value not in manifest_files:
            raise ValueError(f"File with hash {hash_value} not found in manifest")

def validate_fixity(self, fixity, manifest_files):
