def absorb(self, args):
    def absorb_and(operand1, operand2):
        if operand1 == operand2:
            return operand1
        return operator.and_(operand1, operand2)

    def absorb_or(operand1, operand2):
        if operand1 == operand2:
            return operand1
        return operator.or_(operand1, operand2)

    def invert_operand(operand, resulting_operator):
        inverse_operator = operator.eq if resulting_operator == absorb_and else operator.ne
        return lambda x: inverse_operator(operand(x), operand2)

    resulting_args = []
    for i, arg1 in enumerate(args):
        for arg2 in args[i + 1:]:
            resulting_args.append(
                absorb_or(absorb_and(arg1, arg2), absorb_and(invert_operand(arg1, absorb_and),
                    invert_operand(arg2, absorb_or)))
            )
    return resulting_args

def absorb(self, args):
        """
        Given an `args` sequence of expressions, return a new list of expression
        applying absorption and negative absorption.

        See https://en.wikipedia.org/wiki/Absorption_law

        Absorption::

            A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
        """
        result = []
        for arg in args:
            if arg.is_and():
                left, right = arg.left, arg.right
                if left.is_equal(right):
                    result.append(left)
                elif left.is_or() and left.left.is_equal(right):
                    result.append(left.left)
                elif left.is_or() and left.right.is_equal(right):
                    result.append(left.right)
            elif arg.is_or():
                left, right = arg.left, arg.right
                if left.is_equal(right):
                    result.append(left)
                elif left.is_and() and left.left.is_equal(right):
                    result.append(left.right)
                elif left.is_and() and left.right.is_equal(right):
                    result.append(left.left)
            else:
                result.append(arg)
        return result

