def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    >>> relativedelta(days=1.5, hours=2).normalized()
    relativedelta(days=+1, hours=+14)

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """
    # Retrieve all attributes with integer type
    delta = {k: int(getattr(self, k)) for k in self._fields if isinstance(getattr(self, k), int)}
    # Convert any floating point numbers to integer values
    for k, v in delta.items():
        if isinstance(v, float):
            delta[k] = math.ceil(v)
    return relativedelta(**delta)

