def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects, good_objects = 0, 0
    try:
        objects = self.storage_ids()
        num_objects = len(objects)
        for object_id in objects:
            if validate_objects and not self.storage_object_id_exists(object_id):
                raise StorageError("Object not found in registry: " + str(object_id))
            if check_digests and not self.validate_storage_object(object_id):
                raise StorageError("Corrupt object in storage: " + str(object_id))
            else:
                good_objects += 1
        return num_objects, good_objects
    except StorageError:
        return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0

    # Initialize the storage root hierarchy
    hierarchy = self._load_storage_root()

    # Iterate through the hierarchy, validating each object
    for obj in hierarchy.values():
        num_objects += 1

        # Validate the object
        if validate_objects:
            try:
                obj.validate(check_digests=check_digests)
            except Exception:
                if show_warnings:
                    print(f"WARNING: Object {obj.name} is not valid")
                continue

            else:
                good_objects += 1

        # Check the digests
        if check_digests:
            try:
                obj.validate(show_warnings=show_warnings)
            except Exception:
                continue

    return num_objects, good_objects

