def validate_version_inventories(self, version_dirs):
    """
    Each version should have an inventory up to that point.
    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.
    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """

    for version_dir in version_dirs:
        version_dir_path = os.path.join(os.getcwd(), version_dir)
        if os.path.exists(version_dir_path):
            inventory = get_inventory_from_path(version_dir_path)
            if not inventory:
                raise ValueError(f"{version_dir} does not contain a valid inventory file")
            if version_dir not in self.inventory_digests:
                raise ValueError(f"{version_dir} is not present in the root inventory")
            self.inventory_digests[version_dir] = inventory
        else:
            raise ValueError(f"{version_dir} does not exist")

