    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not version_dirs:
        raise ValueError("version_dirs must not be empty")

    root_inventory = self._read_inventory_from_file(self.inventory_file)
    different_digests = []

    for version_dir in version_dirs:
        inventory_path = os.path.join(self.storage_dir, version_dir, self.inventory_file)
        try:
            inventory = self._read_inventory_from_file(inventory_path)
        except FileNotFoundError:
            raise ValueError(f"Version {version_dir} does not have an inventory file")

        for digest in inventory:
            if digest not in root_inventory:
                different_digests.append(digest)
            elif root_inventory[digest] != inventory[digest]:
                different_digests.append(digest)

    return different_digests

