    if not isinstance(version_dirs, list):
        raise TypeError("'version_dirs' must be a list")

    # Iterate over each version directory
    for version_dir in version_dirs:
        # Check if inventory exists for this version
        inventory_path = os.path.join(version_dir, "inventory.json")
        if not os.path.isfile(inventory_path):
            raise ValueError(f"Inventory not found for version '{version_dir}'")

        # Load inventory file
        with open(inventory_path, "r") as f:
            inventory = json.load(f)

        # Check content digests
        root_inventory_path = os.path.join(".", "inventory.json")
        if os.path.isfile(root_inventory_path):
            with open(root_inventory_path, "r") as f:
                root_inventory = json.load(f)
                for key, value in inventory.items():
                    if root_inventory.get(key) != value:
                        raise ValueError(f"Content digests differ for key '{key}' in version '{version_dir}'")

