    """
    Amend the Bugzilla params

    :param params: a dictionary with the params to be updated
    :param bug_ids: a list of strings representing the ids of the bugs to be updated
    """
    for param, value in params.items():
        for bug_id in bug_ids:
            result = self.request('bug/%s/param/%s' % (bug_id, param), 'PUT', json.dump(value))
            if 'error' not in result:
