def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_arguments = {}
    remaining_arguments = []
    for arg in unparsed_arguments:
        # Check if the argument matches a known subparser name
        for parser_name, parser in subparsers.items():
            if arg.startswith(f"{parser_name} "):
                # Remove subparser name from argument and pass to the parser
                parser_argument = arg[len(parser_name):].strip()
                parsed_arguments[parser_name] = parser.parse_known_args(parsed_arguments[parser_name] + [parser_argument])
                break
        else:
            remaining_arguments.append(arg)
    return parsed_arguments, remaining_arguments

def parse_subparser_arguments(unparsed_arguments, subparsers):
