def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size
    """
    sizes = ['B', 'K', 'M', 'G', 'T', 'P', 'E', 'Z', 'Y']

    size = size.upper()
    for idx, si in enumerate(sizes):
        if si in size:
            return int(float(size[:-1]) * (1024 ** (idx + 1)))

    return int(float(size) * 1000)

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    _, num, unit = size.partition(' ')
    base_dict = {'B': 1, 'KB': 1000, 'MB': 1000**2, 'GB': 1000**3, 'TB': 1000**4, 'PB': 1000**5, 'EB': 1000**6, 'ZB': 1000**7, 'YB': 1000**8}
    if unit in base_dict:
        return int(float(num) * base_dict[unit])
    else:
        return int(float(num))

