        digits.append(alphabet[r])
        number //= base

    start_index = 0
    while start_index < len(digits) and digits[start_index] == alphabet[0]:
        start_index += 1

    output = "".join(digits[start_index:])

    if padding > 0:
        output = (padding * alphabet[0])[:padding - len(output)] + output

    return output

