def string_to_int(string: str, alphabet: List[str]) -> int:
    if not string:
        return 0

    base = len(alphabet)
    inverse_alphabet = {v: i for i, v in enumerate(alphabet)}

    n = 0
    for i, d in enumerate(string):
        n += inverse_alphabet[d] * (base ** i)

    return n

