def subprocess_run_helper(func, *args, timeout, extra_env=None):
    if not callable(func):
        raise ValueError("'func' must be callable")
    if not isinstance(timeout, int):
        raise ValueError("'timeout' must be an integer")
    if extra_env is not None and not isinstance(extra_env, dict):
        raise ValueError("'extra_env' must be a dict or None")

    env = {}
    if extra_env:
        env.update(**extra_env)

    with subprocess.Popen(["python", "-c", func.__name__, *args],
                          stdout=subprocess.PIPE,
                          stderr=subprocess.PIPE,
                          env=env,
                          universal_newlines=True) as proc:
        try:
            outs, errs = proc.communicate(timeout=timeout)
            return outs.strip(), errs.strip()
        except subprocess.TimeoutExpired:
            proc.terminate()
            outs, errs = proc.communicate()
            raise subprocess.TimeoutExpired(proc.args, timeout, output=outs.strip(), stderr=errs.strip())
        except Exception as e:
            proc.terminate()
            raise e

def subprocess_run_helper(func, *args, timeout, extra_env=None):
    import subprocess

    if not callable(func):
        raise ValueError('func must be a callable')

    if not isinstance(args, tuple):
        raise ValueError('args must be a tuple')

    if not isinstance(timeout, (int, float)):
        raise ValueError('timeout must be a number')

    if extra_env is not None and not isinstance(extra_env, dict):
        raise ValueError('extra_env must be a dict')

    cmd = [func.__module__, func.__name__] + list(args)

    proc = subprocess.Popen(cmd, timeout=timeout, env=extra_env)

    try:
        out = proc.communicate()[0]
    except subprocess.TimeoutExpired:
        proc.kill()
        out = None

    return out

