def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    todo = Queue()
    done = set()
    if roots is None:
        roots = set()

    for node in graph.nodes():
        if not node in roots and not graph.has_edge(node, prop):
            # node IS NOT A ROOT
            todo.push(node)
            continue
        done.add(node)

    while True:
        if todo:
            node = todo.pop()
        elif not done:
            break
        else:
            roots.add(node)
            for child in graph.get_children(node):
                if child not in done:
                    todo.push(child)
            continue

        seen = set()
        for child in graph.get_children(node):
            if child in done:
                seen.add(child)

        for child in seen:
            if not graph.has_edge(child, prop):
                todo.push(child)

    return roots

