    if roots is None:
        roots = set()
    seen = set()
    for node in graph:
        if node not in seen:
            seen.add(node)
            for _, p, child in graph.triples((None, prop, node)):
                if child not in seen:
                    seen.add(child)
                    find_roots(graph, prop, roots)
    return roots

