def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin: bin.content
    if get_coordinate == "left":
        get_coordinate_func = lambda bin: bin.left
    elif get_coordinate == "right":
        get_coordinate_func = lambda bin: bin.right
    else:
        get_coordinate_func = lambda bin: (bin.left + bin.right) / 2
    graph_points = []
    for bin in hist:
        point = make_value(bin)
        if not isinstance(point, tuple):
            point = (point,)
        coordinate = get_coordinate_func(bin)
        graph_point = GraphPoint(coordinate=coordinate, value=point)
        graph_points.append(graph_point)
    if scale is True:
        scale = hist.scale
    graph = Graph(scale=scale if scale is not None else None)
    graph.add_points(graph_points)
    return graph

