        if line.startswith('```') and not code_block:
            code_block = True
        elif line.startswith('```') and code_block:
            code_block = False
        elif not code_block:
            for word in line.split():
                if word.startswith('# '):
                    tag = word[2:].strip()
                    tags.add(tag)
