def find_tags(text, replacer=None):
    """Find tags in text.

    Args:
        text (str): Text to search for tags in.
        replacer (callable, optional): Optional function to use to replace tags with the result.

    Returns:
        Tuple[Set, str]: A set of unique tags found in the text, and the original or replaced text.
    """
    tags = set()
    code_blocks = []
    lines = text.splitlines()

    for line in lines:
        if "```" in line:
            code_blocks.append(line)
        else:
            for word in line.split():
                if word.startswith("```"):
                    code_blocks.append(word)
                elif word.endswith("```"):
                    code_blocks.append(word)

    for line in lines:
        for word in line.split():
            if word.startswith("#") and word not in code_blocks:
                if replacer is None:
                    tags.add(word)
                else:
                    tags.add(replacer(word))

    if replacer is None:
        return tags, text
    else:
        return tags, text.replace(word, replacer(word))

