def verify_relayable_signature(public_key, doc, signature):
    # Check that the signature is properly formed and corresponds to the public key
    try:
        crypto.validate_signature(doc, signature, pubkey=public_key)
    except crypto.InvalidMessageSignature:
        return False

    # Check that the message is properly formatted and meets the requirements
    try:
        # Validate the format of the message
        valid_message = crypto.validate_message_format(doc)
        # Verify that the message is properly relayable
        relayable = crypto.verify_relayable_message(valid_message)
    except crypto.MessageValidationError:
        return False

    return relayable

