  const algorithm = 'rsa-sha256';
  const signedElements = [...document.querySelectorAll('SignedInfo')].map(el => el.textContent);
  const verifiedElements = signedElements.filter(el => crypto.verify(algorithm, el, public_key, signature));
  if (verifiedElements.length !== signedElements.length) {
    throw new Error('Invalid signature');
  }
  return verifiedElements;
};

