def get_plugin_spec_flatten_dict(plugin_dir):
    """Retrieves a flatten dictionary of plugin properties from a plugin spec file.

    :param plugin_dir: The path to the plugin's directory.

    Returns:
        A flatten dictionary of plugin properties.
    """
    flatten_dict = {}
    spec_filepath = os.path.join(plugin_dir, "plugin.spec")
    with open(spec_filepath, "r") as f:
        spec_file_str = f.read()
    spec_dict = json.loads(spec_file_str)
    for key, value in spec_dict.items():
        if isinstance(value, dict):
            flatten_dict.update(get_plugin_spec_flatten_dict(value))
        elif isinstance(value, list):
            for item in value:
                if isinstance(item, dict):
                    flatten_dict.update(get_plugin_spec_flatten_dict(item))

    return flatten_dict

